// One item per PDF attachment. Emails with no PDF go to the error branch.
const out = [];
for (const item of $input.all()) {
  const bin = item.binary || {};
  const pdfs = Object.keys(bin).filter(k => (bin[k].mimeType || '').includes('pdf') || /\.pdf$/i.test(bin[k].fileName || ''));
  const base = { messageId: item.json.id, receivedAt: item.json.receivedDateTime };
  if (pdfs.length === 0) { out.push({ json: { ...base, hasPdf: false, errors: ['no PDF attachment'] } }); continue; }
  for (const k of pdfs) out.push({ json: { ...base, hasPdf: true, fileName: bin[k].fileName }, binary: { data: bin[k] } });
}
return out;

// Northfield invoice capture: same rules as simulate.py extract()
const MONTHS = {jan:1,feb:2,mar:3,apr:4,may:5,jun:6,jul:7,aug:8,sep:9,oct:10,nov:11,dec:12};
const AMT = '([0-9][0-9,]*\\.[0-9]{2})';
const money = s => s == null ? null : Math.round(parseFloat(s.replace(/,/g, '')) * 100);
const fmt = p => (p / 100).toFixed(2);
function iso(y, m, d) {
  const dt = new Date(Date.UTC(+y, +m - 1, +d));
  if (dt.getUTCFullYear() != +y || dt.getUTCMonth() != +m - 1 || dt.getUTCDate() != +d) return null;
  return dt.toISOString().slice(0, 10);
}
function invoiceDate(text) {
  const out = [];
  for (const m of text.matchAll(/\b(\d{4})-(\d{2})-(\d{2})\b/g)) out.push([m.index, iso(m[1], m[2], m[3])]);
  for (const m of text.matchAll(/\b(\d{1,2})\/(\d{1,2})\/(\d{4})\b/g)) out.push([m.index, iso(m[3], m[2], m[1])]);
  for (const m of text.matchAll(/\b(\d{1,2})\s+([A-Za-z]{3})[a-z]*\.?\s+(\d{4})\b/g)) {
    const mon = MONTHS[m[2].toLowerCase()]; if (mon) out.push([m.index, iso(m[3], mon, m[1])]);
  }
  out.sort((a, b) => a[0] - b[0]);
  for (const [pos, d] of out) {
    if (!d) continue;
    if (!/due|pay by|payable/i.test(text.slice(Math.max(0, pos - 15), pos))) return d;
  }
  return null;
}
function supplier(text) {
  let m = text.match(/^\s*From:\s*([^,\n]+)/mi); if (m) return m[1].trim();
  m = text.match(/^\s*(.+?)\s+[—–-]+\s+invoice\b/mi); if (m) return m[1].trim();
  for (let line of text.split('\n')) {
    line = line.trim();
    if (!line || /invoice|date|total|vat|\d/i.test(line)) continue;
    return line;
  }
  return null;
}
function invoiceNumber(text) {
  for (const re of [/\bNo\.\s*([A-Z0-9][A-Z0-9\/\-]*)/i, /#\s*([A-Z0-9][A-Z0-9\/\-]*)/i,
                    /\binvoice\s+(?:number|no)?\s*:?\s*([A-Z]{1,6}[\/\-][A-Z0-9\/\-]+)/i]) {
    const m = text.match(re); if (m && /\d/.test(m[1])) return m[1];
  }
  return null;
}
function extract(text) {
  const f = {supplier: supplier(text), invoice_no: invoiceNumber(text), date: invoiceDate(text), currency: 'GBP'};
  let t = text.match(new RegExp('\\btotal(?:\\s+due)?\\b[\\s.:]*(?:£|GBP)?\\s*' + AMT, 'i'));
  let v = text.match(new RegExp('\\bVAT(?:\\s*\\d{1,2}(?:\\.\\d+)?%)?[\\s.:]*£?\\s*' + AMT, 'i'));
  let n = text.match(new RegExp('\\b(?:net|subtotal)\\b[\\s.:]*£?\\s*' + AMT, 'i'));
  let total = t ? money(t[1]) : null, vat = v ? money(v[1]) : null, net = n ? money(n[1]) : null;
  const noVat = /\bno VAT\b|not VAT registered/i.test(text);
  if (total == null) { const a = [...text.matchAll(new RegExp('£\\s*' + AMT, 'g'))]; if (a.length == 1) total = money(a[0][1]); }
  if (vat == null && noVat) vat = 0;
  if (net == null && total != null && vat != null) net = total - vat;
  const errors = [];
  if (!/\binvoice\b/i.test(text) || /\bno invoice\b/i.test(text)) errors.push('not an invoice (no invoice wording, or says no invoice)');
  Object.assign(f, {net, vat, total});
  for (const k of ['supplier', 'invoice_no', 'date', 'net', 'vat', 'total']) if (f[k] == null) errors.push('missing ' + k);
  if (net != null && vat != null && total != null && Math.abs(net + vat - total) > 1)
    errors.push(`net + VAT (${fmt(net + vat)}) does not equal total (${fmt(total)})`);
  for (const k of ['net', 'vat', 'total']) if (f[k] != null) f[k] = fmt(f[k]);
  return {fields: f, errors};
}

// n8n Code node, mode: Run Once for Each Item
const r = extract($json.text || '');
const f = r.fields;
return { json: {
  messageId: $('Split PDF attachments').item.json.messageId,
  fileName: $('Split PDF attachments').item.json.fileName,
  ...f, errors: r.errors, valid: r.errors.length === 0,
  xeroBody: r.errors.length ? null : { Invoices: [{
    Type: 'ACCPAY', Status: 'DRAFT', Contact: { Name: f.supplier }, InvoiceNumber: f.invoice_no,
    Date: f.date, CurrencyCode: f.currency, LineAmountTypes: 'Exclusive',
    LineItems: [{ Description: `Invoice ${f.invoice_no} from ${f.supplier}`, Quantity: 1,
      UnitAmount: f.net, TaxType: Number(f.vat) > 0 ? 'INPUT2' : 'NONE', TaxAmount: f.vat }] }] }
} };

// Build the operations-support alert. File name and reasons only: never the email body
// or attachment, so no client data leaves the client's own tools.
return $input.all().map(i => ({ json: {
  to: 'operations-support',
  workflow: 'northfield-invoice-capture',
  execution: $execution.id,
  messageId: i.json.messageId || null,
  item: i.json.fileName || ('email ' + (i.json.messageId || 'unknown')),
  reasons: i.json.errors || [(i.json.execution && i.json.execution.error && i.json.execution.error.message) || (i.json.error && (i.json.error.message || String(i.json.error))) || 'unknown error'],
  action: 'Follow run-book section 4 (re-run a failed item)'
} }));

